const items = $input.all();
const output = [];

const TIME_ZONE = 'Asia/Seoul';

// -----------------------------------------
// 날짜/시간 Utility
// -----------------------------------------

// Date 객체를 한국 시간 기준 정보로 변환
function getKSTParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);

  const get = (type) =>
    parts.find(p => p.type === type)?.value;

  return {
    year: get('year'),
    month: get('month'),
    day: get('day'),
    hour: Number(get('hour')),
    minute: Number(get('minute')),
  };
}


// Date/ISO timestamp → 한국 기준 YYYY-MM-DD
function getKSTDateString(dateValue) {
  const date = new Date(dateValue);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const get = (type) =>
    parts.find(p => p.type === type)?.value;

  return `${get('year')}-${get('month')}-${get('day')}`;
}


// YYYY-MM-DD에서 하루 빼기
function subtractOneDay(dateString) {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() - 1);

  return date.toISOString().slice(0, 10);
}


// 한국 시간 ISO 문자열 생성
function makeKSTDateTime(dateString, hour) {
  const hh = String(hour).padStart(2, '0');

  return `${dateString}T${hh}:00:00+09:00`;
}


// -----------------------------------------
// 현재 한국 시간
// -----------------------------------------

const nowKST = getKSTParts();

const todayString =
  `${nowKST.year}-${nowKST.month}-${nowKST.day}`;

const currentMinutes =
  (nowKST.hour * 60) + nowKST.minute;


// 발송 슬롯
const SLOT_10 = 10 * 60;
const SLOT_16 = 16 * 60;
const SLOT_19 = 19 * 60;


// -----------------------------------------
// 각 상담 데이터 처리
// -----------------------------------------

for (const item of items) {

  const {
    consultation_id,
    customer_id,
    customer_name,
    reconsultation_at,
    store_id,
    staff_id,
    privacy_consent,
    recontact_consent,
    schedule_type,
  } = item.json;


  // ---------------------------------------
  // 필수 데이터 검증
  // ---------------------------------------

  if (!reconsultation_at) {
    throw new Error(
      `reconsultation_at이 없습니다. consultation_id=${consultation_id}`
    );
  }


  // 실제 재상담 날짜
  const reconsultationDate =
    getKSTDateString(reconsultation_at);

  if (!reconsultationDate) {
    throw new Error(
      `reconsultation_at 형식이 올바르지 않습니다. consultation_id=${consultation_id}`
    );
  }


  // ---------------------------------------
  // 재상담이 오늘 또는 이미 지난 경우
  // 스케줄 생성하지 않음
  // ---------------------------------------

  if (reconsultationDate <= todayString) {
    continue;
  }


  // 재상담 하루 전
  const reminderDate =
    subtractOneDay(reconsultationDate);


  let scheduledHour = null;


  // ---------------------------------------
  // CASE 1
  // D-1이 미래 날짜
  // → 오전 10시
  // ---------------------------------------

  if (reminderDate > todayString) {

    scheduledHour = 10;

  }


  // ---------------------------------------
  // CASE 2
  // D-1이 오늘
  // → 가능한 다음 발송 슬롯 선택
  // ---------------------------------------

  else if (reminderDate === todayString) {

    if (currentMinutes < SLOT_10) {
      scheduledHour = 10;
    }

    else if (currentMinutes < SLOT_16) {
      scheduledHour = 16;
    }

    else if (currentMinutes < SLOT_19) {
      scheduledHour = 19;
    }

    else {
      // 오후 7시 이후
      // 더 이상 발송하지 않음
      continue;
    }

  }


  // ---------------------------------------
  // CASE 3
  // D-1 자체가 이미 지난 경우
  // ---------------------------------------

  else {
    continue;
  }


  const scheduledContactAt =
    makeKSTDateTime(reminderDate, scheduledHour);


  // ---------------------------------------
  // 최종 스케줄 item 생성
  // ---------------------------------------

  output.push({
    json: {

      consultation_id,
      customer_id,
      customer_name,

      store_id,
      staff_id,

      schedule_type,

      privacy_consent,
      recontact_consent,

      reconsultation_at,

      reference_date: reconsultationDate,

      schedule_subtype: 'reconsultation_1d_before',

      scheduled_contact_date: reminderDate,

      scheduled_contact_at: scheduledContactAt,

      contact_reason: '재상담 1일 전 안내',

      selected_send_slot: `${String(scheduledHour).padStart(2, '0')}:00`
    }
  });

}

return output;
